<?php
session_start();
$env=__DIR__.'/.env'; if(is_file($env)) foreach(file($env,FILE_IGNORE_NEW_LINES|FILE_SKIP_EMPTY_LINES) as $l){if(strpos(trim($l),'#')===0||strpos($l,'=')===false)continue;[$k,$v]=explode('=',$l,2);putenv(trim($k).'='.trim($v));}
$pass=getenv('USAGE_APP_PASSWORD')?:''; $file=__DIR__.'/usage.json'; if(!is_file($file))file_put_contents($file,'{"openai":[],"claude":[],"updated_at":null}');
function e($s){return htmlspecialchars((string)$s,ENT_QUOTES,'UTF-8');} function data($f){$d=json_decode(@file_get_contents($f),true);return is_array($d)?$d:[];}
if(($_POST['a']??'')==='login'&&$pass!==''&&hash_equals($pass,$_POST['p']??'')){session_regenerate_id(true);$_SESSION['ok']=1;header('Location:/');exit;} if(($_POST['a']??'')==='out'){session_destroy();header('Location:/');exit;}
if(empty($_SESSION['ok'])){?><!doctype html><meta name=viewport content="width=device-width"><style><?php include 'style.css';?></style><main class=login><h1>AI Usage</h1><p>Private dashboard</p><form method=post><input type=hidden name=a value=login><input type=password name=p placeholder=Password required><button>Sign in</button></form></main><?php exit;}
$d=data($file);?><!doctype html><meta name=viewport content="width=device-width"><title>AI Usage</title><style><?php include 'style.css';?></style><header><h1>AI Usage</h1><form method=post><input type=hidden name=a value=out><button>Sign out</button></form></header><main><p class=notice>Private dashboard is online. Provider browser sync will be connected next.</p><section><?php foreach(['openai'=>'OpenAI / Codex','claude'=>'Claude'] as $k=>$name){$x=$d[$k]??[];?><article><h2><?=e($name)?></h2><b><?=e($x['remaining']??'—')?></b><p>Remaining</p><small>Used: <?=e($x['used']??'—')?> · Reset: <?=e($x['reset']??'—')?></small></article><?php }?></section></main>
